member.summary:
Returns a Nullable struct from the stream.
The value returned must be cast to the correct Nullable type.
Synonym for ReadObject();

example.code:
public class ExampleSingletonEvent : ModSingletonEvent<ExampleSingletonEvent>
{

    public static readonly int CascadeLevel = CASCADE_EQUIPMENT | CASCADE_EXCEPT_THROWN_WEAPON;

    public bool Test;

    public static bool Check(GameObject Object)
    {
        Object.HandleEvent(Instance);
        var result = Instance.Test;
        Instance.Reset();

        return result;
    }

    public override void Reset()
    {
        base.Reset();
        Test = false;
    }

    public override int GetCascadeLevel()
    {
        return CascadeLevel;
    }

}

public class ExamplePooledEvent : ModPooledEvent<ExamplePooledEvent>
{

    public static readonly int CascadeLevel = CASCADE_EQUIPMENT | CASCADE_EXCEPT_THROWN_WEAPON;

    public bool Test;

    public static bool Check(GameObject Object)
    {
        var E = FromPool();
        Object.HandleEvent(E);
        var result = E.Test;
        ResetTo(ref E);

        return result;
    }

    public override void Reset()
    {
        base.Reset();
        Test = false;
    }

    public override int GetCascadeLevel()
    {
        return CascadeLevel;
    }

}

member.summary:
The object's display name without adjectives, clauses, or tags;
only alterations to the display name that are considered core
to the object's identity are included.

example.code:
public class ExampleHandler : IPart, IModEventHandler<ExampleEvent>
{

    public override bool WantEvent(int ID, int Cascade)
    {
        return base.WantEvent(ID, Cascade)
              || ID == ExampleEvent.ID
            ;
    }

    public bool HandleEvent(ExampleEvent E)
    {
       E.Test = true;
      return true;
    }

}

